WITH parsed AS (SELECT id, coupon_codes, items, attributes, COALESCE(attributes['device'], 'direct') AS device_or_default, TRANSFORM(FILTER(items, li -> li.promo IS NOT NULL), li -> STRUCT(li.product_id AS pid, ROUND(li.price * 0.9, 2) AS discounted_price)) AS promo_lines, COALESCE(attributes['utm_source'], 'none') AS utm_source_or_default, COALESCE(attributes['gift'], 'direct') AS gift_or_default, AGGREGATE(items, 0.0D, (acc, li) -> acc + li.qty * li.price, acc -> ROUND(acc, 2)) AS basket_amount FROM carts WHERE ARRAY_CONTAINS(coupon_codes, 'BUNDLE')) SELECT id, coupon_codes, items, attributes, device_or_default, promo_lines, utm_source_or_default, gift_or_default, basket_amount, LAST_VALUE(utm_source_or_default) IGNORE NULLS OVER (ORDER BY basket_amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_utm_source_or_default, ROW_NUMBER() OVER (ORDER BY basket_amount, id) AS row_seq, AVG(basket_amount) OVER (ORDER BY basket_amount, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS basket_amount_avg_6_prior FROM parsed;
